export type ClusterStreamError = { "kind": "ClusterLagged",
/**
 * Number of cluster events dropped because the subscriber fell behind.
 *
 * Exported to TypeScript as `number`; see the module docs for the accepted `2^53` ceiling.
 */
skipped: number, };

export type MessageRole = { "role": "User" } | { "role": "Assistant" } | { "role": "System" } | { "role": "Tool" };

export type ProgressDetail = { "detail": "UsageEstimate",
/**
 * Estimated input (prompt) tokens consumed so far, when the harness reports it.
 */
input_tokens: number | null,
/**
 * Estimated output (completion) tokens produced so far, when the harness reports it.
 */
output_tokens: number | null, } | { "detail": "Note",
/**
 * The progress note text.
 */
text: string, };

export type StopKind = { "stop": "EndTurn" } | { "stop": "ToolUse" } | { "stop": "LimitReached" } | { "stop": "Cancelled" } | { "stop": "Error",
/**
 * Human-readable error description.
 */
message: string, } | { "stop": "Other",
/**
 * The harness's raw stop-reason label.
 */
reason: string, };

export type AgentOutcome = {
/**
 * The whole run output: every completed agent answer, accumulated by the harness.
 */
text: string,
/**
 * The run's LAST completed agent answer message, alone and exactly as the agent said it.
 *
 * Reasoning, tool output, and user turns never enter this field. It exists separately from
 * [`Self::text`] so an exact-token judge reads the actual final verdict rather than falsely
 * failing a successful run because narration from earlier answers precedes it. It is empty when
 * the agent produced no answer text at all, and equals `text` when there was exactly one answer.
 */
final_message: string,
/**
 * The canonical `snake_case` stop reason
 * ([`StopKind::canonical_stop_reason`]).
 */
stop_reason: string,
/**
 * The handle of the conversation that produced this outcome.
 *
 * A FACT, not a promise: the id names the session the harness actually
 * ran — minted, loaded, or derived by that harness — and says nothing
 * about whether it can be resumed. Resumability is the per-agent question
 * a harness's own handshake answers (for ACP, the `initialize` response's
 * `loadSession` capability), never something this field asserts.
 *
 * The id is meaningful only to the harness that minted it; resume routing
 * pairs the id with the harness identity the workflow record already
 * carries. It is never empty — a harness with a vacant handle is refused
 * at [`AgentOutcome::into_payload`], not shipped.
 */
session_id: string, };

export type ActivityEventKind = { "kind": "Message",
/**
 * Who the message is attributed to.
 */
role: MessageRole,
/**
 * The message text.
 */
text: string, } | { "kind": "ToolCall",
/**
 * The tool/function name.
 */
tool: string,
/**
 * Correlation id linking this call to its eventual [`Self::ToolResult`].
 */
call_id: string,
/**
 * The structured tool input.
 */
input: unknown, } | { "kind": "ToolResult",
/**
 * Correlation id matching the originating [`Self::ToolCall`].
 */
call_id: string,
/**
 * The structured tool output.
 */
output: unknown,
/**
 * Whether the tool reported an error result.
 */
is_error: boolean, } | { "kind": "Progress",
/**
 * The progress detail.
 */
detail: ProgressDetail, } | { "kind": "Stop",
/**
 * Why the run stopped.
 */
reason: StopKind, } | { "kind": "Raw",
/**
 * A label identifying where the raw value came from (adapter-defined).
 */
source: string,
/**
 * The raw value, passed through verbatim.
 */
value: unknown, } | { "kind": "Delta",
/**
 * The id of the message this fragment belongs to.
 */
message_id: string,
/**
 * The incremental text fragment.
 */
text_fragment: string, };

export type ActivityEvent = {
/**
 * The workflow this activity belongs to.
 */
workflow_id: WorkflowId,
/**
 * The concrete run of that workflow this event was produced in — the second stream axis.
 *
 * Required. Two generations of one continue-as-new chain share a `workflow_id` and restart
 * their ordinals and attempts, so this is the only field that keeps their transcripts apart.
 */
run_id: RunId,
/**
 * The activity within the workflow.
 */
activity_id: ActivityId,
/**
 * The attempt number of the activity this event was produced during.
 */
attempt: number,
/**
 * Sub-identity of the agent that produced this event — REQUIRED for multi-agent
 * attribution (a single activity attempt may run several agents).
 */
agent_id: string,
/**
 * The role/label of the producing agent (e.g. an orchestrator vs a sub-agent).
 */
agent_role: string,
/**
 * Producer-clock instant the event was emitted (best-effort ordering hint).
 */
emitted_at: string,
/**
 * Worker-local best-effort monotonic sequence.
 *
 * Exported to TypeScript as `number`; see the module docs for the accepted `2^53` ceiling.
 */
worker_seq: number,
/**
 * Server-stamped monotonic sequence assigned at durable-commit time; `None` until the event
 * is persisted (ephemeral events are never persisted and always carry `None`).
 *
 * Exported to TypeScript as `number`; see the module docs for the accepted `2^53` ceiling.
 */
store_seq: number | null,
/**
 * When `true`, this event is WS-forward-only and is **never persisted** (token deltas).
 */
ephemeral: boolean,
/**
 * The classified payload of this event.
 */
kind: ActivityEventKind, };

export type InjectPriority = { "priority": "Normal" } | { "priority": "Interrupt" };

export type ApprovalDecision = { "decision": "Approve" } | { "decision": "Deny" };

export type InterventionPrimitive = { "primitive": "InjectMessage" } | { "primitive": "Cancel" } | { "primitive": "PauseResume" } | { "primitive": "UpdateBudget" } | { "primitive": "RespondToApproval" };

export type InterventionKind = { "kind": "InjectMessage",
/**
 * The message text to inject.
 */
text: string,
/**
 * Whether to act now (`Interrupt`) or queue the turn (`Normal`).
 */
priority: InjectPriority, } | { "kind": "Cancel",
/**
 * Human-readable reason for the cancellation.
 */
reason: string, } | { "kind": "PauseResume",
/**
 * `true` to suspend, `false` to resume.
 */
paused: boolean, } | { "kind": "UpdateBudget",
/**
 * New maximum token budget, when the operator sets one.
 */
max_tokens: number | null,
/**
 * New maximum turn budget, when the operator sets one.
 */
max_turns: number | null, } | { "kind": "RespondToApproval",
/**
 * Correlation id of the pending approval being answered.
 */
call_id: string,
/**
 * The approve/deny decision.
 */
decision: ApprovalDecision,
/**
 * An optional note recorded alongside the decision.
 */
note: string | null, };

export type InterventionCommand = {
/**
 * The workflow the target activity belongs to.
 */
workflow_id: WorkflowId,
/**
 * The concrete run of that workflow the target attempt belongs to.
 *
 * Required, and load-bearing for routing: a continue-as-new chain reuses one
 * `workflow_id` while ordinals and attempts restart in each generation, so without the run
 * axis a command aimed at generation two would resolve generation one's owner. Delivering a
 * steer to the wrong generation is a control-plane fault, not a display bug.
 */
run_id: RunId,
/**
 * The target activity within the workflow.
 */
activity_id: ActivityId,
/**
 * The target attempt. Commands to a stale (superseded) attempt are no-ops.
 */
attempt: number,
/**
 * The auth subject that issued the command, when auth is enabled.
 *
 * A neutral subject label (the same identity the auth layer records), carried so the
 * transcript can attribute the intervention. `None` when auth is off.
 */
issued_by: string | null,
/**
 * When the command was issued (operator-clock instant).
 */
issued_at: string,
/**
 * The neutral control primitive to apply.
 */
kind: InterventionKind, };

export type InterventionCapabilities = {
/**
 * The primitives this harness supports. Empty = observability-only.
 */
supported: Array<InterventionPrimitive>, };

export type InterventionOutcome = { "outcome": "Applied" } | { "outcome": "CapabilityNotSupported",
/**
 * The primitive the target does not support.
 */
primitive: InterventionPrimitive, } | { "outcome": "StaleTarget",
/**
 * Human-readable detail describing why the target is stale.
 */
detail: string, };

export type StepState = { "state": "Scheduled" } | { "state": "Dispatched",
/**
 * One-based delivery attempt recorded on the `ActivityStarted`.
 */
attempt: number,
/**
 * When the ENGINE dispatched — NOT when a worker took it.
 */
dispatched_at: string, } | { "state": "Reopened",
/**
 * `recorded_at` of the `WorkflowReopened` that re-opened the ordinal.
 */
reopened_at: string, };

export type OpenStep = {
/**
 * Activity ordinal recorded in history.
 */
activity_id: ActivityId,
/**
 * Activity type the step runs.
 */
activity_type: string,
/**
 * Task queue stamped on the recorded `ActivityScheduled` — the address the
 * dispatch really went to, never a re-resolution that could disagree.
 */
task_queue: string,
/**
 * Node affinity stamped on the recorded `ActivityScheduled`, if any.
 */
node: string | null,
/**
 * `recorded_at` of the `ActivityScheduled` that opened the ordinal.
 */
scheduled_at: string,
/**
 * How far the step has got in the recorded lifecycle.
 */
state: StepState, };

export type AttemptLiveness = { "liveness": "Live",
/**
 * The owning worker's advertised intervention capabilities.
 */
capabilities: InterventionCapabilities, } | { "liveness": "NoLiveOwner" };

export type HeartbeatNote = { "note": "Reported",
/**
 * The worker's opaque progress payload, exactly as it was sent.
 */
payload: Payload,
/**
 * When this server process received the reporting heartbeat.
 */
reported_at: string, } | { "note": "NoneSent" } | { "note": "Unavailable",
/**
 * When this server process began holding progress notes.
 */
notes_held_since: string,
/**
 * True when the attempt was dispatched BEFORE this process began
 * holding notes — a restart demonstrably explains the absence.
 */
restarted_since_attempt_began: boolean, };

export type TranscriptTail = { "transcript": "NotRequested" } | { "transcript": "Window",
/**
 * The retained events, in `store_seq` order, each carrying its
 * `store_seq`. Empty when the stream has nothing retained.
 */
events: Array<ActivityEvent>,
/**
 * Next durable `store_seq` for the stream at read time.
 */
head_seq: number,
/**
 * Retained records BEFORE this window, omitted by the requested bound.
 * Read the full stream with `POST /workflows/transcript`.
 */
omitted_before: number,
/**
 * The retention cap has closed this stream: the cap marker is the last
 * durable record and every later event is live-only, never persisted.
 *
 * A reader seeing the last retained event on a truncated stream is
 * seeing the end of the RETENTION, not the end of the agent's output.
 */
retention_truncated: boolean, };

export type LiveAttempt = {
/**
 * One-based delivery attempt this view describes.
 */
attempt: number,
/**
 * When the engine dispatched this attempt.
 */
dispatched_at: string,
/**
 * Whether a connected worker owns the attempt right now.
 */
liveness: AttemptLiveness,
/**
 * The most recent worker progress note, or a typed reason there is none.
 */
note: HeartbeatNote,
/**
 * The bounded tail of the attempt's retained transcript.
 */
transcript: TranscriptTail, };

export type CurrentStep = {
/**
 * The step itself, as history records it.
 */
step: OpenStep,
/**
 * The live view of the dispatched attempt.
 *
 * `None` when the step is [`StepState::Scheduled`] or
 * [`StepState::Reopened`]: there is no attempt yet, so there is nothing
 * that could be live, could have sent a note, or could have a transcript.
 * That is a structural absence, not a missing measurement.
 */
attempt: LiveAttempt | null, };

export type TranscriptStreamHead = {
/**
 * The activity within the workflow.
 */
activity_id: ActivityId,
/**
 * The attempt — the third stream axis. Two attempts of one activity are
 * DISTINCT streams.
 */
attempt: number,
/**
 * The activity type this stream belongs to, resolved from the run's own
 * history. `None` when the run's history records no scheduling for the
 * ordinal (a stream retained from a segment this history no longer holds).
 */
activity_type: string | null,
/**
 * Next `store_seq` to be written == count of retained records.
 */
head_seq: number,
/**
 * Whether this stream is the current step's dispatched attempt.
 */
current: boolean,
/**
 * The retention cap has closed this stream (see
 * [`TranscriptTail::Window::retention_truncated`]).
 */
retention_truncated: boolean, };

export type DescribeLiveResponse = {
/**
 * Workflow summary projected from authoritative history (carrying the
 * projected status), when the workflow exists.
 */
summary: WorkflowSummary | null,
/**
 * The single step a reader is told the run is on: the open step whose last
 * history event is the most recent. `None` when the run is not inside an
 * activity at all (completed, failed, or blocked on a timer or signal).
 */
current_step: CurrentStep | null,
/**
 * EVERY open step, in the order the ordinals were opened.
 *
 * A fan-out has several steps open at once, and [`Self::current_step`]
 * reports one of them. This list is how a reader sees the siblings rather
 * than having to know they might exist.
 */
open_steps: Array<OpenStep>,
/**
 * Every retained transcript stream of the workflow, annotated with the
 * activity type it belongs to and whether it is the current attempt's.
 */
transcript_streams: Array<TranscriptStreamHead>,
/**
 * Every activity this run's history records as dispatched and unterminated
 * that the live fleet cannot currently serve.
 *
 * EMPTY is the healthy answer and the only healthy one — see
 * [`UnservedActivity`], whose semantics this field shares exactly (it is
 * the same projection `POST /workflows/describe` returns).
 */
unserved: Array<UnservedActivity>, };

